    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == 'half_up' else n // 10000

    def solve(data):
        cutoff = data.get('cutoff', 10**9)
        chosen = {}
        for pos, event in enumerate(data['events']):
            seq = event.get('sequence', 0)
            if seq > cutoff:
                continue
            ident = event.get('id', 'anonymous:' + str(pos))
            key = ((seq, event.get('revision', 0), pos) if sequence_first
                   else (event.get('revision', 0), pos))
            if ident not in chosen or key > chosen[ident][0]:
                chosen[ident] = (key, event)

        balances = dict(data.get('opening', {}))
        for _, event in chosen.values():
            if event.get('void', False):
                continue
            raw = event['price'] * event.get('quantity', 1)
            discount = min(10000, max(0, event.get('discount_bp', 0)))
            net = rounded(raw * (10000 - discount), data['rounding'])
            base = net if discounted else raw
            tax = rounded(base * event.get('tax_bp', 0), data['rounding'])
            amount = net + tax
            if event.get('kind') == 'refund':
                amount = -amount
            key = event.get('account', 'default') + '|' + event.get('currency', 'USD')
            balances[key] = balances.get(key, 0) + amount
        return {'balances': balances}
    return solve


def _dependencies():
    from itertools import product

    def solve(data):
        packages = data['packages']
        names = sorted(packages)
        features = set(data.get('features', []))
        blocked = data.get('blocked', {})
        pins = data.get('pins', {})
        roots = data['roots']
        rows = {name: {row['version']: row for row in packages[name]} for name in names}
        choices = [[-1] + sorted(rows[name]) for name in names]

        def valid(assignment):
            installed = {name: version for name, version in zip(names, assignment)
                         if version != -1}
            for name, (low, high) in roots.items():
                version = installed.get(name)
                if version is None or not low <= version <= high:
                    return False
            for name, version in installed.items():
                if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                    return False

            edges = {name: [] for name in installed}
            closure = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in closure:
                    continue
                closure.add(name)
                version = installed.get(name)
                if version is None:
                    return False
                for dep in rows[name][version].get('deps', []):
                    feature = dep.get('feature', '')
                    if feature and feature not in features:
                        continue
                    other = dep['name']
                    other_version = installed.get(other)
                    if (other_version is None or
                            not dep['min'] <= other_version <= dep['max']):
                        return False
                    edges[name].append(other)
                    stack.append(other)
            if closure != set(installed):
                return False

            active, done = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                done.add(name)
                return True
            return all(visit(name) for name in names if name in installed)

        for assignment in product(*choices):
            if valid(assignment):
                return {'versions': {name: version for name, version in zip(names, assignment)
                                     if version != -1}}
        return {'error': 'unsatisfiable'}
    return solve


def _jobs():
    from itertools import combinations
    def solve(data):
        k = data['k']
        blocked = set(data.get('blocked', []))
        mandatory = set(data.get('mandatory', []))
        options = [job for job in data['jobs'] if job['id'] not in blocked]
        if not mandatory.issubset({job['id'] for job in options}):
            return {'error': 'impossible'}
        best_value = None
        best_ids = None
        quotas = data.get('quotas', {})
        for selected in combinations(options, k):
            ids = tuple(sorted(job['id'] for job in selected))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selected:
                counts[job['group']] = counts.get(job['group'], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(selected, key=lambda job: (job['start'], job['end']))
            if any(ordered[i]['start'] < ordered[i - 1]['end']
                   for i in range(1, len(ordered))):
                continue
            value = sum(job['value'] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {'error': 'impossible'}
        return {'selected': list(best_ids), 'value': best_value}
    return solve


def _routes():
    import heapq
    def solve(data):
        required = data.get('required', [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bits.get(data['source'], 0)
        graph = [[] for _ in range(data['n'])]
        for edge in data['edges']:
            graph[edge['u']].append(edge)
        start_state = (data['source'], initial_mask, data['coupons'])
        dist = {start_state: data['start']}
        queue = [(data['start'],) + start_state]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data['target'] and mask == full and remaining == 0:
                return {'arrival': time}
            for edge in graph[node]:
                depart = max(time, edge['open'])
                if depart >= edge['close']:
                    continue
                v = edge['v']
                next_mask = mask | bits.get(v, 0)
                durations = [(edge['duration'], remaining)]
                if remaining:
                    duration = max(2, edge['duration'] - edge.get('discount', 0))
                    durations.append((duration, remaining - 1))
                for duration, next_remaining in durations:
                    arrival = depart + duration
                    if arrival > data['deadline']:
                        continue
                    next_state = (v, next_mask, next_remaining)
                    if arrival < dist.get(next_state, float('inf')):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival,) + next_state)
        return {'arrival': None}
    return solve


